/* Browser-local onboarding prototype. It is not a verified parental-consent system. */
(()=>{
'use strict';
const key='diabuddy-onboarding-v1', defaults=()=>({step:'welcome',role:'',children:[{nickname:'',age:'',pet:'bunny',name:'Miso',clothes:'shirt',accessory:'bow'}],index:0,ack:false,done:false});
let data;try{data={...defaults(),...JSON.parse(localStorage.getItem(key)||'{}')}}catch{data=defaults()}
const pets=['bunny','cat','dragon','fox','alien'];
const esc=escapeHTML;
let dialog=document.createElement('dialog');dialog.id='onboarding';dialog.setAttribute('aria-labelledby','onboard-title');document.body.appendChild(dialog);
const child=()=>data.children[data.index];
function persist(){try{localStorage.setItem(key,JSON.stringify(data));return true}catch{const e=dialog.querySelector('#onboard-error');if(e)e.textContent='We couldn’t save your progress. Check browser storage and try again.';return false}}
function step(next){data.step=next;if(persist())draw()}
function open(){if(!dialog.open)dialog.showModal();draw()}
function goBack(){const s=data.step;if(s==='role')return step('welcome');if(s==='demo')return step('role');if(s==='count')return step('role');if(s==='nickname'){if(data.role==='parent'&&data.index>0){data.index--;return step('age')}return step(data.role==='parent'?'count':'role')}if(s==='age')return step('nickname');if(s==='pet')return step('age');if(s==='customize')return step('pet');if(s==='handoff')return step('customize');if(s==='devices')return step('age');if(s==='connections')return step('devices');if(s==='reminders')return step('connections');if(s==='parentpets')return step('reminders');if(s==='disclaimer')return step(data.role==='kid'?'handoff':'parentpets');if(s==='plan')return step('disclaimer');if(s==='summary')return step('plan');if(s==='complete')return step('disclaimer')}
function previewQuestionnaire(role,index=0){
 const childSteps=[
  ['What should your buddy call you?','Example nickname: Sunny. In the finished experience, this can be changed later.'],
  ['How old are you?','Example age: 10. The finished experience will include an accessible age picker.'],
  ['Who do you want as your buddy?','Explore a selection of buddies with illustrated previews.'],
  ['Let’s make your buddy yours!','Example buddy: Miso, wearing a sage shirt and lavender bow.'],
  ['Let’s invite your grown-up to help finish setup.','A grown-up will help with the required consent and account linking.'],
  ['You and Miso are ready!','Your buddy can’t wait to explore with you.']
 ];
 const parentSteps=[
  ['How many children with type 1 diabetes are you setting up?','Example: two child profiles.'],
  ['What nickname should we use?','Example: Sunny, age 10. Each child will have a separate profile.'],
  ['Does your child use a continuous glucose monitor?','Optional choices: Dexcom, another CGM, no CGM, or skip.'],
  ['Does your child use an insulin pump?','Optional choices: Tandem t:slim X2, another pump, no pump, or skip.'],
  ['Device connections and reminders','Optional connections and reminders can be set up later.'],
  ['Time to meet their buddy!','Each child can choose a buddy or create one later.'],
  ['A buddy for learning and everyday routines','DiaBuddy supports learning and routines. It does not provide medical advice, recommend insulin doses or timing, replace your care team or device alerts, or provide emergency monitoring.'],
  ['Choose the right plan for your family','Free: basic features for any number of children. Plus: one child, $5.99 monthly or $50 annually. Family: up to five children, $8.99 monthly. Paid plans are not available yet.'],
  ['Welcome to your DiaBuddy family!','Review child profiles, buddy choices, and optional settings before continuing.']
 ];
 if(!role){dialog.innerHTML=`<div class="onboard-shell"><div class="onboard-brand">✿ &nbsp; DiaBuddy</div><div class="onboard-note">QUESTIONNAIRE PREVIEW · FICTIONAL EXAMPLES ONLY</div><h1 id="onboard-title" tabindex="-1">Which questionnaire would you like to see?</h1><div class="onboard-choices"><button id="preview-kid">🐾 &nbsp; Kid or teen</button><button id="preview-parent">♡ &nbsp; Parent or caregiver</button></div><div class="onboard-actions"><button class="secondary" id="preview-exit">← Back</button></div></div>`;dialog.querySelector('#preview-kid').onclick=()=>previewQuestionnaire('kid');dialog.querySelector('#preview-parent').onclick=()=>previewQuestionnaire('parent');dialog.querySelector('#preview-exit').onclick=draw;}
 else{const items=role==='kid'?childSteps:parentSteps,[title,text]=items[index];const showPet=role==='kid'&&(index===2||index===3);dialog.innerHTML=`<div class="onboard-shell"><div class="onboard-brand">✿ &nbsp; DiaBuddy</div><p class="onboard-note">QUESTIONNAIRE PREVIEW · FICTIONAL EXAMPLES ONLY</p><div class="onboard-progress" aria-label="Step ${index+1} of ${items.length}"><span>YOUR LITTLE JOURNEY</span><span>${index+1} / ${items.length}</span><div><i style="width:${(index+1)/items.length*100}%"></i></div></div><h1 id="onboard-title" tabindex="-1">${esc(title)}</h1><div class="onboard-body"><p>${esc(text)}</p>${showPet?'<canvas id="preview-buddy" width="180" height="160" aria-label="Example buddy illustration"></canvas>':''}</div><div class="onboard-actions"><button class="secondary" id="preview-back">← Back</button><button class="primary" id="preview-next">${index===items.length-1?'Finish preview':'Next →'}</button></div></div>`;dialog.querySelector('#preview-back').onclick=()=>index?previewQuestionnaire(role,index-1):previewQuestionnaire(null);dialog.querySelector('#preview-next').onclick=()=>index===items.length-1?draw():previewQuestionnaire(role,index+1);if(showPet)paintWorld(dialog.querySelector('#preview-buddy'),'cozy',{Characters:'bunny',Clothes:'shirt',Accessories:'bow'},'range','Idle',true,true);}
 dialog.querySelector('#onboard-title').focus();
}
function draw(){if(!['welcome','role','demo'].includes(data.step))data.step='demo';const s=data.step,c=child();let title='',body='',next='',back=s!=='welcome',stepNumber=0,total=data.role==='parent'?10:7;
if(s==='welcome'){title='Hi! Welcome to DiaBuddy! 🐾';body='<p>Life with type 1 diabetes comes with a lot to learn. Your DiaBuddy is here to make everyday routines a little more fun—with a pet of your own, games, and activities along the way!</p><button class="secondary" id="preview-questionnaire">Preview the questionnaire</button> <button class="secondary" type="button" data-family-demo>Try family linking demo</button>';next='Let’s get started!'}
if(s==='role'){title='Are you a kid or a parent?';stepNumber=1;body='<div class="onboard-choices"><button data-role="kid">🐾 &nbsp; I’m a kid or teen</button><button data-role="parent">♡ &nbsp; I’m a parent or caregiver</button></div>';}
if(s==='demo'){title='Explore DiaBuddy together';body='<p>Try the demo with imaginary information. Please don’t enter a child’s personal or health information.</p><p class="onboard-note">Child profiles and health connections will be available after the family privacy and consent features are ready. Parent account setup is coming soon.</p>';next='Explore the demo'}
if(s==='count'){title='How many children with type 1 diabetes are you setting up?';stepNumber=2;body=`<p>Optional questions can be skipped, and you can update your choices later.</p><label for="child-count">Number of children</label><input id="child-count" type="number" min="1" max="10" value="${data.children.length}"><p class="onboard-note">This prototype stores setup on this browser only. It does not provide secure separate accounts or protect profiles from other people using this browser.</p>`;next='Continue'}
if(s==='nickname'){title=data.role==='kid'?'What should your buddy call you?':`What nickname should we use for child ${data.index+1}?`;stepNumber=data.role==='kid'?2:3;body=`<p>Just a nickname, not your full name. You can change it later.</p><label for="onboard-name">Nickname</label><input id="onboard-name" maxlength="24" autocomplete="off" value="${esc(c.nickname)}">`;next='Continue'}
if(s==='age'){title=data.role==='kid'?'How old are you?':'How old are they?';stepNumber=data.role==='kid'?3:3;body=`<p>Choose an age. Your answers stay in this browser in this prototype.</p><label for="onboard-age">Age</label><select id="onboard-age"><option value="">Choose an age</option>${Array.from({length:21},(_,i)=>`<option value="${i}" ${String(c.age)===String(i)?'selected':''}>${i===20?'20 or older':i}</option>`).join('')}</select>`;next='Continue'}
if(s==='pet'){title='Who do you want as your buddy?';stepNumber=4;body=`<p>Pick a friend. You can change your choice later.</p><div class="onboard-pets" role="group" aria-label="Choose your buddy">${pets.map(id=>`<button type="button" aria-pressed="${c.pet===id}" class="pet-choice ${c.pet===id?'selected':''}" data-pet="${id}"><canvas data-pet-art="${id}" width="120" height="110" aria-hidden="true"></canvas><span>${esc(PixelPets[id].name.split(' · ')[1])}</span></button>`).join('')}</div>`;next='Continue'}
if(s==='customize'){title='Let’s make your buddy yours!';stepNumber=5;body=`<p>Give your buddy a name and a look. You can change these later.</p><canvas id="onboard-preview" width="180" height="160" aria-label="Your buddy preview"></canvas><label for="pet-name">Buddy’s name</label><input id="pet-name" maxlength="24" value="${esc(c.name)}"><label for="pet-clothes">Outfit color</label><select id="pet-clothes"><option value="shirt" ${c.clothes==='shirt'?'selected':''}>Sage shirt</option><option value="pink" ${c.clothes==='pink'?'selected':''}>Pink cardigan</option><option value="galaxy" ${c.clothes==='galaxy'?'selected':''}>Purple hoodie</option></select><label for="pet-accessory">Accessory</label><select id="pet-accessory"><option value="none" ${c.accessory==='none'?'selected':''}>None</option><option value="bow" ${c.accessory==='bow'?'selected':''}>Lavender bow</option><option value="hat" ${c.accessory==='hat'?'selected':''}>Sprout hat</option></select>`;next='Continue'}
if(s==='handoff'){title='Let’s invite your grown-up to help finish setup.';stepNumber=6;body='<p>Your buddy is here to help you learn and play. Your grown-up and diabetes team help with insulin and treatment decisions.</p><p class="onboard-note">Please hand this device to your parent or caregiver. Your choices are saved here. This prototype cannot verify a caregiver or collect legally valid parental consent.</p>';body+='<div class="onboard-choices"><button type="button" id="grownup-here">My grown-up is here</button><button type="button" disabled>Connect with my grown-up’s account · Not available yet</button></div>';next=''}
if(s==='devices'){title='Devices (optional)';stepNumber=4;body='<p>Device choices aren’t collected in this prototype. You can explore the simulated device panels in the parent portal later.</p><p class="onboard-note">Dexcom sandbox uses simulated data; Tandem is not connected.</p>';next='Skip for now'}
if(s==='connections'){title='Device connections (optional)';stepNumber=5;body='<p>Dexcom’s official sandbox connection is available from the parent portal when configured. It uses simulated glucose readings to change the buddy’s animation. DiaBuddy never asks for your provider password.</p><p>Tandem connection: <strong>Not available yet.</strong></p><p class="onboard-note">No health data is accessed during setup. A connection is never required.</p>';next='Skip for now'}
if(s==='reminders'){title='Routine reminders (optional)';stepNumber=6;body='<p>Reminders are off for setup. Scheduled caregiver-configured reminders are not available in this prototype yet. The existing reminders page offers simulated demos and optional system notifications.</p><p class="onboard-note">No notification permission will be requested during setup.</p>';next='Skip for now'}
if(s==='parentpets'){title='Time to meet their buddy!';stepNumber=7;body='<p>Your family can personalize a buddy in the app. This prototype supports one active companion on this browser; separate child accounts are not available yet.</p>';next='Let them create it later'}
if(s==='disclaimer'){title='A buddy for learning and everyday routines';stepNumber=data.role==='kid'?7:8;body=`<p>DiaBuddy makes life with type 1 diabetes more approachable through virtual pets, educational activities, and games to enjoy during waiting time. DiaBuddy does not provide medical advice, recommend insulin doses or pre-bolus timing, or replace your diabetes care team, prescribed care plan, or medical device alerts. Always follow your care team’s instructions for treatment decisions. DiaBuddy is not an emergency monitoring service.</p><p class="onboard-note">For a parent or caregiver: This prototype stores information on this device and does not yet have published Privacy Policy or Terms, secure accounts, or a verified parental-consent process. Please do not enter real health information. Acknowledgment is not consent to access health data.</p><label class="onboard-check"><input id="onboard-ack" type="checkbox" ${data.ack?'checked':''}> I understand DiaBuddy’s role and limitations.</label>`;next='Continue'}
if(s==='plan'){title='Choose the right plan for your family';stepNumber=9;body=`<p>Continue with the Free experience. Paid plans are not available yet.</p><div class="onboard-plan-list"><section class="onboard-plan"><h2>Free</h2><p>${esc(window.DiaPlans.free.description)}</p><button type="button" class="primary" id="choose-free">Continue with Free</button></section><section class="onboard-plan"><h2>Plus</h2><p>$${(window.DiaPlans.plusMonthly.amountCents/100).toFixed(2)} per month or $${(window.DiaPlans.plusAnnual.amountCents/100).toFixed(2)} per year. Features and profile limits are being decided.</p><button type="button" disabled>Choose Plus · Not available yet</button></section><section class="onboard-plan"><h2>Family</h2><p>$${(window.DiaPlans.familyMonthly.amountCents/100).toFixed(2)} per month. Features and profile limits are being decided.</p><button type="button" disabled>Choose Family · Not available yet</button></section></div>`;}
if(s==='summary'){title='Welcome to your DiaBuddy family!';stepNumber=10;body=`<p>Review your setup. You can return to any step to make changes.</p><ul>${data.children.map((x,i)=>`<li>Child ${i+1}: ${esc(x.nickname||'No nickname')} · age ${esc(x.age)}</li>`).join('')}</ul><p>Buddy: Create later · Connections: Not connected · Reminders: Off</p><button class="secondary" id="edit-profiles">Edit child profiles</button><p class="onboard-note">These are setup notes, not secure or separate child accounts.</p>`;next='Go to Parent Portal'}
if(s==='complete'){title=`You and ${esc(c.name||'Miso')} are ready!`;body='<p>Your buddy can’t wait to explore with you.</p>';next='Meet my buddy'}
dialog.innerHTML=`<div class="onboard-shell"><div class="onboard-brand">✿ &nbsp; DiaBuddy</div>${stepNumber?`<div class="onboard-progress" aria-label="Step ${stepNumber} of ${total}"><span>YOUR LITTLE JOURNEY</span><span>${stepNumber} / ${total}</span><div><i style="width:${stepNumber/total*100}%"></i></div></div>`:''}<h1 id="onboard-title" tabindex="-1">${title}</h1><div class="onboard-body">${body}</div><p id="onboard-error" role="alert"></p><div class="onboard-actions">${back?'<button class="secondary" id="onboard-back">← Back</button>':''}${next?`<button class="primary" id="onboard-next">${next}</button>`:''}</div></div>`;
dialog.querySelector('#onboard-title').focus();dialog.querySelector('#preview-questionnaire')?.addEventListener('click',()=>previewQuestionnaire(null));dialog.querySelector('#onboard-back')?.addEventListener('click',goBack);
dialog.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{data.role=b.dataset.role;data.index=0;step('demo')});
dialog.querySelectorAll('[data-pet]').forEach(b=>b.onclick=()=>{c.pet=b.dataset.pet;if(persist())draw()});
dialog.querySelectorAll('[data-pet-art]').forEach(canvas=>paintWorld(canvas,'cozy',{Characters:canvas.dataset.pet},'range','Idle',true,true));
const preview=()=>{const canvas=dialog.querySelector('#onboard-preview');if(canvas)paintWorld(canvas,'cozy',{Characters:c.pet,Clothes:c.clothes,Accessories:c.accessory==='none'?null:c.accessory},'range','Idle',true,true)};preview();
for(const [id,prop] of [['pet-name','name'],['pet-clothes','clothes'],['pet-accessory','accessory']]){const el=dialog.querySelector('#'+id);if(el)el.addEventListener('input',()=>{c[prop]=el.value;persist();preview()})}
for(const [id,prop] of [['onboard-name','nickname'],['onboard-age','age']]){const el=dialog.querySelector('#'+id);if(el)el.addEventListener('input',()=>{c[prop]=el.value;persist()})}
dialog.querySelector('#grownup-here')?.addEventListener('click',()=>step('disclaimer'));
dialog.querySelector('#choose-free')?.addEventListener('click',()=>{data.plan='free';step('summary')});
dialog.querySelector('#edit-profiles')?.addEventListener('click',()=>{data.index=0;step('count')});
dialog.querySelector('#onboard-next')?.addEventListener('click',()=>{const error=dialog.querySelector('#onboard-error');if(s==='welcome')return step('role');if(s==='demo'){data.done=true;if(!persist()){data.done=false;return}dialog.close();go('home');return}if(s==='count'){const n=Number(dialog.querySelector('#child-count').value);if(!Number.isInteger(n)||n<1||n>10){error.textContent='Choose a number from 1 to 10.';return}while(data.children.length<n)data.children.push({nickname:'',age:'',pet:'bunny',name:'Miso',clothes:'shirt',accessory:'bow'});data.children.length=n;data.index=0;return step('nickname')}if(s==='nickname'){c.nickname=dialog.querySelector('#onboard-name').value.trim();if(!c.nickname){error.textContent='Please choose a nickname.';return}return step('age')}if(s==='age'){c.age=dialog.querySelector('#onboard-age').value;if(c.age===''){error.textContent='Please choose an age.';return}if(data.role==='kid')return step('pet');if(data.index<data.children.length-1){data.index++;return step('nickname')}data.index=0;return step('devices')}if(s==='pet')return step('customize');if(s==='customize'){c.name=dialog.querySelector('#pet-name').value.trim()||'Miso';return step('handoff')}if(s==='handoff')return step('disclaimer');if(s==='devices')return step('connections');if(s==='connections')return step('reminders');if(s==='reminders')return step('parentpets');if(s==='parentpets')return step('disclaimer');if(s==='disclaimer'){data.ack=dialog.querySelector('#onboard-ack').checked;if(!data.ack){error.textContent='Please ask your grown-up to read and acknowledge this note.';return}return step(data.role==='kid'?'complete':'plan')}if(s==='complete'||s==='summary'){if(data.role==='kid'){state.characterName=c.name||'Miso';state.equipped.Characters=c.pet;state.equipped.Clothes=c.clothes;state.equipped.Accessories=c.accessory==='none'?null:c.accessory;for(const id of [c.pet,c.clothes,c.accessory])if(id&&id!=='none'&&!state.owned.includes(id))state.owned.push(id);try{save()}catch{error.textContent='We couldn’t save your buddy. Please try again.';return}}data.done=true;if(!persist()){data.done=false;return}dialog.close();go('home');if(data.role==='parent'){const selector=document.querySelector('#portal-select');selector.value='parent';selector.dispatchEvent(new Event('change',{bubbles:true}))}}})}
dialog.addEventListener('cancel',e=>e.preventDefault());
window.DiaOnboarding={stopForCare(){if(dialog.open)dialog.close();},open:()=>{data.step='welcome';open()}};
if(!data.done&&(!window.diaExistingUser||localStorage.getItem(key)))open();
})();
